import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

layernorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void layer_norm_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int inner_size,
    float eps)
{
    int batch = blockIdx.x;
    const float* x_ptr = x + (long)batch * inner_size;
    float* out_ptr = out + (long)batch * inner_size;

    extern __shared__ float sdata[];
    float* ssum = sdata;
    float* ssumsq = sdata + blockDim.x;

    float sum = 0.f;
    float sumsq = 0.f;

    for (int i = threadIdx.x; i < inner_size; i += blockDim.x) {
        float v = x_ptr[i];
        sum += v;
        sumsq += v * v;
    }

    ssum[threadIdx.x] = sum;
    ssumsq[threadIdx.x] = sumsq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            ssum[threadIdx.x] += ssum[threadIdx.x + s];
            ssumsq[threadIdx.x] += ssumsq[threadIdx.x + s];
        }
        __syncthreads();
    }

    __shared__ float mean;
    __shared__ float inv_std;

    if (threadIdx.x == 0) {
        mean = ssum[0] / inner_size;
        float var = ssumsq[0] / inner_size - mean * mean;
        inv_std = rsqrtf(var + eps);
    }
    __syncthreads();

    for (int i = threadIdx.x; i < inner_size; i += blockDim.x) {
        float v = x_ptr[i];
        float norm = (v - mean) * inv_std;
        out_ptr[i] = norm * weight[i] + bias[i];
    }
}

torch::Tensor layer_norm_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    double eps)
{
    auto out = torch::empty_like(x);

    int batch_size = x.size(0);
    long total_elems = x.numel();
    int inner_size = (int)(total_elems / batch_size);

    int threads = 1024;
    int blocks = batch_size;
    size_t shared_mem = 2 * threads * sizeof(float);

    layer_norm_kernel<<<blocks, threads, shared_mem>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        inner_size,
        (float)eps
    );

    return out;
}
"""

layernorm_cpp_source = r"""
torch::Tensor layer_norm_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

layernorm_module = load_inline(
    name="layernorm_module",
    cpp_sources=layernorm_cpp_source,
    cuda_sources=layernorm_source,
    functions=["layer_norm_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs Layer Normalization using a custom CUDA kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self.layernorm_module = layernorm_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()
        return self.layernorm_module.layer_norm_cuda(x, weight, bias, self.eps)


batch_size = 16
features = 64
dim1 = 256
dim2 = 256

def get_inputs():
    x = torch.rand(batch_size, features, dim1, dim2).cuda()
    return [x]

def get_init_inputs():
    return [(features, dim1, dim2)]

